insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m1', 'Тефтели из индейки с гречкой', 'Обед', '25 мин работы · 50 мин всего', 6, false, '[1, 2, 3]'::jsonb, '["Мелко нарежьте лук. Смешайте с фаршем, яйцом и небольшим количеством соли. Сформируйте 18 тефтелей.", "В форму выложите томаты, разомните их, добавьте 150 мл воды. Положите тефтели, накройте фольгой. Запекайте при 190 °C 30 минут, затем ещё 10 минут без фольги.", "Гречку промойте, залейте примерно 840 мл воды. После закипания варите под крышкой на слабом огне 15–20 минут; дайте постоять 5 минут.", "Разделите тефтели и гречку на 6 порций. Подайте с выбранным салатом из категории «Салаты». Проверьте готовность птицы: 74 °C в центре самого толстого кусочка. Время зависит от духовки и размера порций."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
