insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m2', 'Чечевичное рагу с тыквой, хлебом и йогуртом', 'Ужин', '20 мин работы · 40 мин всего', 6, false, '[1, 2, 3]'::jsonb, '["Тыкву нарежьте кубиками 1,5–2 см, морковь и лук — мельче. Чечевицу промойте.", "В большой кастрюле на масле прогрейте лук и морковь 5 минут, помешивая. Добавьте тыкву, томаты, чечевицу и 900 мл воды.", "Доведите до кипения, убавьте огонь. Варите 20–25 минут до мягкости чечевицы и тыквы; при необходимости долейте 100–300 мл воды.", "Попробуйте, умеренно посолите. Разделите на 6 порций. К каждой подайте 60 г хлеба и 100 г йогурта."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
