insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m3', 'Курица, булгур и запечённые овощи', 'Обед', '20 мин работы · 45 мин всего', 4, false, '[4, 5]'::jsonb, '["Духовку разогрейте до 200 °C. Курицу нарежьте кусочками 3 см, морковь — тонкими брусочками, кабачок — полукружьями.", "Смешайте курицу и овощи с маслом, небольшим количеством соли и сушёными травами. Разложите на большом противне в один слой.", "Запекайте 25–35 минут, один раз перемешайте. Проверьте готовность птицы: 74 °C в центре самого толстого кусочка. Время зависит от духовки и размера порций.", "Булгур залейте примерно 560 мл воды, варите по упаковке 15–20 минут. Йогурт смешайте с укропом и чесноком; соус храните отдельно.", "Разделите всё на 4 порции. Соус добавляйте непосредственно перед едой."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
