insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m4', 'Лосось / форель с картофелем', 'Ужин', '15 мин работы · 40 мин всего', 4, false, '[4, 5]'::jsonb, '["Картофель тщательно вымойте, нарежьте дольками с кожурой. Смешайте с половиной масла, запекайте при 200 °C 20 минут.", "Рыбу разделите на 4 порции. В отдельную форму положите рыбу, укроп, лимон и оставшееся масло.", "Поставьте рыбу в духовку на 12–18 минут, картофель оставьте допекаться рядом. Готовая рыба легко разделяется вилкой; ориентир в центре — 63 °C. Удалите кости перед подачей.", "Разделите рыбу и картофель на 4 порции. К каждой порции добавьте выбранный салат из категории «Салаты»."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
