insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m5', 'Болоньезе с чечевицей и цельнозерновыми макаронами', 'Обед', '25 мин работы · 45 мин всего', 4, false, '[6, 7]'::jsonb, '["Лук мелко нарежьте, морковь натрите. Обжарьте на масле 5 минут на среднем огне.", "Добавьте фарш, разбейте комочки лопаткой и готовьте 7–8 минут. Всыпьте промытую чечевицу, добавьте томаты и 350 мл воды.", "Тушите под неплотной крышкой 20–25 минут до мягкости чечевицы. Помешивайте, при загустении добавляйте воду. Фарш должен полностью приготовиться, ориентир 71 °C.", "Макароны отварите по упаковке. Разделите макароны и соус на 4 порции. Подайте с выбранным салатом из категории «Салаты»."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
