insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m6', 'Домашняя шаурма с курицей', 'Ужин', '25 мин работы · 40 мин всего', 4, false, '[6, 7]'::jsonb, '["Курицу смажьте маслом, приправьте сушёными травами и небольшим количеством соли. Запеките при 200 °C 25–35 минут. Проверьте готовность птицы: 74 °C в центре самого толстого кусочка. Время зависит от духовки и размера порций.", "Нашинкуйте капусту, натрите морковь. Огурцы нарежьте перед сборкой. Йогурт смешайте с чесноком.", "Разделите курицу на 4 порции, нарежьте полосками. Начинку, соус и лаваш храните отдельно.", "На порцию лаваша выложите овощи и курицу, добавьте соус. Подверните края и сверните. Подрумяньте на сухой сковороде по 1–2 минуты с каждой стороны."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
