insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m7', 'Куриные сердечки с грибами и перловкой', 'Обед', '30 мин работы · 80–100 мин всего', 6, false, '[8, 9, 10]'::jsonb, '["Перловку промойте; для ускорения можно замочить на ночь в холодильнике. Варите в большом количестве воды до мягкости по упаковке, обычно 40–60 минут; лишнюю воду слейте.", "У сердечек срежьте сосуды и лишний жир, разрежьте вдоль пополам, удалите сгустки крови. Лук измельчите, морковь нарежьте кружочками, грибы — пластинками.", "На 25 мл масла прогрейте лук и морковь 5 минут. Добавьте сердечки, готовьте 5–7 минут, помешивая. Влейте 350 мл горячей воды, накройте и тушите на слабом огне 40 минут.", "Добавьте грибы и тушите ещё 20–30 минут до мягкости сердечек; если нужно, продлите приготовление и долейте немного горячей воды. Сердечки должны прогреться минимум до 74 °C внутри, а для мягкости может понадобиться больше времени.", "Разделите сердечки с грибами и перловку на 6 порций. Выбранный салат готовьте по отдельной карточке в категории «Салаты»."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
