insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m8', 'Мягкий чили из индейки и фасоли', 'Ужин', '20 мин работы · 40 мин всего', 6, false, '[8, 9, 10]'::jsonb, '["Промойте фасоль, дайте стечь. Лук, морковь и кабачок нарежьте небольшими кубиками.", "На масле готовьте лук и морковь 5 минут. Добавьте фарш и разбивайте комки ещё 7–8 минут.", "Добавьте томаты, кабачок и 150 мл воды, тушите 15 минут. Всыпьте фасоль, прогрейте ещё 5–7 минут. Проверьте готовность птицы: 74 °C в центре самого толстого кусочка. Время зависит от духовки и размера порций.", "Булгур сварите по упаковке примерно в 720 мл воды. Разделите на 6 порций, подайте с чили и укропом. Острый соус по желанию добавляется отдельно."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
