insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m9', 'Котлеты из индейки с гречкой', 'Обед', '25 мин работы · 45 мин всего', 4, false, '[11, 12]'::jsonb, '["Кабачок натрите и слегка отожмите. Смешайте с фаршем, измельчённым луком, яйцом и небольшим количеством соли.", "Сформируйте 8 котлет. Выложите на смазанный противень и запекайте при 190 °C 25–30 минут. Проверьте готовность птицы: 74 °C в центре самого толстого кусочка. Время зависит от духовки и размера порций.", "Гречку промойте, сварите под крышкой примерно в 560 мл воды за 15–20 минут.", "Разделите котлеты и гречку на 4 порции. Выбранный салат собирайте перед едой."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
