insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m10', 'Дорадо / сибас с картофелем и фасолью', 'Ужин', '15 мин работы · 40 мин всего', 2, false, '[11]'::jsonb, '["Картофель нарежьте дольками, смешайте с 10 мл масла, запекайте при 200 °C 30–40 минут.", "Филе обсушите, положите в отдельную форму, добавьте лимон, укроп и 5 мл масла. Запекайте 12–20 минут в зависимости от толщины. Готовая рыба легко разделяется вилкой; ориентир в центре — 63 °C. Удалите кости перед подачей.", "Фасоль отварите 5–7 минут. Подайте всё на двоих.", "Чтобы не готовить гарнир завтра, сразу приготовьте картофель и фасоль также из рецепта дня 12. Их количество в покупках уже посчитано отдельно."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
