insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m11', 'Картофельный салат с консервированными сардинами', 'Ужин', '10 мин со сваренным картофелем', 2, false, '[12]'::jsonb, '["Картофель отварите до мягкости 20–25 минут или используйте приготовленный накануне. Фасоль варите 5–7 минут. Охладите и храните в холодильнике.", "Перед едой нарежьте картофель и огурец. С сардин слейте жидкость; крупные твёрдые кости удалите, мягкие съедобные косточки можно размять.", "Соедините с фасолью, укропом, лимонным соком и маслом. Если рыба была в масле, дополнительное масло можно не использовать.", "Разделите на две порции. Соль добавляйте только после пробы; салат собирайте непосредственно перед едой."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
