insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m12', 'Густой куриный суп с белой фасолью', 'Обед', '20 мин работы · 45 мин всего', 4, false, '[13, 14]'::jsonb, '["Курицу нарежьте кубиками, залейте 1,5 л воды. Доведите до кипения, снимите пену и варите 15 минут.", "Нарежьте картофель, морковь, лук и капусту; добавьте к курице. Варите ещё 15–20 минут до мягкости.", "Фасоль промойте и добавьте в суп за 5 минут до конца. Умеренно посолите, добавьте укроп. Проверьте готовность птицы: 74 °C в центре самого толстого кусочка. Время зависит от духовки и размера порций.", "Разделите всю кастрюлю на 4 порции, равномерно распределяя мясо и овощи. Подайте с хлебом."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
