insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m13', 'Нут с тыквой, булгуром и яйцом', 'Ужин', '20 мин работы · 40 мин всего', 4, false, '[13, 14]'::jsonb, '["Тыкву нарежьте кубиками, смешайте с маслом. Запекайте при 200 °C 25–30 минут до мягкости.", "Булгур сварите примерно в 480 мл воды по упаковке. Яйца сварите вкрутую 9–10 минут после закипания, остудите.", "Нут промойте и прогрейте в сотейнике с 2–3 ложками воды. Йогурт смешайте с укропом.", "На каждую из 4 порций выложите крупу, нут и тыкву, добавьте яйцо и соус. Компоненты храните отдельно."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
