insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m14', 'Ленивые голубцы с индейкой', 'Обед', '30 мин работы · 70 мин всего', 6, false, '[15, 16, 17]'::jsonb, '["Рис промойте и варите в воде около 20–25 минут до полуготовности; слейте воду.", "Капусту тонко нашинкуйте и помните; жёсткую капусту залейте кипятком на 5 минут и отожмите. Морковь натрите, лук измельчите.", "Смешайте овощи, фарш и рис. Выложите в смазанную глубокую форму слоем не толще 5 см.", "Томаты смешайте с 350 мл воды, залейте форму. Накройте фольгой, запекайте при 190 °C 40–50 минут; при необходимости долейте горячую воду.", "Проверьте мягкость риса и готовность птицы (74 °C в центре). Разделите на 6 порций; подайте с йогуртом и свежим огурцом."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
