insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m15', 'Куриные бёдра с картофелем и морковью', 'Ужин', '20 мин работы · 60 мин всего', 6, false, '[15, 16, 17]'::jsonb, '["Возьмите мякоть бёдер без кожи и костей. Картофель нарежьте дольками, морковь — брусочками. Смешайте с курицей, 25 мл масла и чесноком.", "Распределите на большом противне, запекайте при 200 °C 40–50 минут. В середине перемешайте овощи. Проверьте готовность птицы: 74 °C в центре самого толстого кусочка. Время зависит от духовки и размера порций.", "Разделите курицу и гарнир на 6 порций. Подайте с выбранным салатом из категории «Салаты»."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
