insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m16', 'Тёплый салат из чечевицы, курицы и овощей', 'Обед', '25 мин работы · 45 мин всего', 4, false, '[18, 19]'::jsonb, '["Чечевицу промойте, варите в большом количестве воды 20–30 минут по упаковке до мягкости, не разваривая. Слейте воду.", "Курицу и овощи нарежьте. Смешайте с 20 мл масла, запекайте при 200 °C 25–35 минут. Проверьте готовность птицы: 74 °C в центре самого толстого кусочка. Время зависит от духовки и размера порций.", "Соедините тёплую чечевицу, курицу и овощи. Разделите на 4 порции.", "Перед подачей добавьте укроп, сок лимона и оставшееся масло; подайте хлеб. Холодные порции сначала разогрейте."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
