insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m17', 'Атлантическая скумбрия с картофелем', 'Ужин', '15 мин работы · 45 мин всего', 2, false, '[18]'::jsonb, '["Картофель отварите до мягкости 20–25 минут или запеките. Если сразу готовите на завтра, прибавьте картофель из рецепта дня 19 — в покупках он уже учтён.", "Филе скумбрии положите в форму, добавьте лимон. Запекайте при 190 °C 20–25 минут. Готовая рыба легко разделяется вилкой; ориентир в центре — 63 °C. Удалите кости перед подачей.", "Подайте на двоих с картофелем и выбранным салатом из отдельной категории. Компоненты выбранного салата можно подготовить заранее по его рецепту."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
