insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m18', 'Сельдь с картофелем и яйцом', 'Ужин', '10 мин с готовыми овощами', 2, false, '[19]'::jsonb, '["Картофель отварите заранее до мягкости. Яйца сварите вкрутую 9–10 минут и охладите.", "Откройте готовую солёную сельдь перед едой, проверьте филе на кости и нарежьте.", "На каждого подайте 80 г сельди, одно яйцо, половину картофеля и укропа. Дополните выбранным салатом из категории «Салаты».", "Овощи дополнительно не досаливайте. Сельдь храните по сроку на упаковке."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
