insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m19', 'Мягкое карри из курицы и нута', 'Обед', '20 мин работы · 40 мин всего', 4, false, '[20, 21]'::jsonb, '["Лук и морковь нарежьте, припустите в масле 5 минут. Добавьте ½–1 ч. л. мягкой смеси карри без болгарского перца или куркуму с кумином.", "Курицу нарежьте кубиками, добавьте в сотейник и готовьте 5 минут, помешивая.", "Влейте томаты и 150 мл воды, тушите под крышкой 20 минут. Добавьте промытый нут и прогрейте 5 минут. Проверьте готовность птицы: 74 °C в центре самого толстого кусочка. Время зависит от духовки и размера порций.", "Булгур сварите по упаковке. Разделите блюдо на 4 порции, огурец нарежьте при подаче."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
