insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m20', 'Фриттата с кабачком, горошком и сыром', 'Ужин', '20 мин работы · 50 мин всего', 4, false, '[20, 21]'::jsonb, '["Картофель нарежьте дольками, смажьте 15 мл масла и поставьте в духовку при 190 °C на 40–45 минут.", "Кабачок нарежьте мелкими кубиками. На оставшемся масле готовьте 5–7 минут, чтобы испарилась лишняя влага; добавьте горошек на 2 минуты.", "Взбейте яйца с молоком, вмешайте тёртый сыр. Овощи положите в форму, залейте смесью.", "Запекайте рядом с картофелем 25–35 минут до полного схватывания середины, ориентир 71 °C. Разделите на 4 порции. Подайте с картофелем и выбранным салатом из отдельной категории."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
