insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m21', 'Курица с гречкой и грибами в духовке', 'Обед', '25 мин работы · 60 мин всего', 6, false, '[22, 23, 24]'::jsonb, '["Грибы нарежьте пластинками, лук измельчите. Прогрейте на масле 7–8 минут.", "В глубокую форму положите промытую гречку, грибы и лук. Влейте около 850 мл горячей воды, слегка посолите.", "Сверху выложите кусочки курицы, накройте фольгой. Запекайте при 190 °C 40 минут, затем проверьте крупу и допеките 10 минут без фольги. Проверьте готовность птицы: 74 °C в центре самого толстого кусочка. Время зависит от духовки и размера порций.", "Разделите курицу и гречку на 6 порций. К ним приготовьте выбранный салат из категории «Салаты»."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
