insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m22', 'Чечевичный суп и тост с сыром', 'Ужин', '20 мин работы · 40 мин всего', 6, false, '[22, 23, 24]'::jsonb, '["Лук нарежьте, морковь натрите. Прогрейте на масле 5 минут в большой кастрюле.", "Добавьте промытую чечевицу, томаты и 1,3 л воды. Варите 20–25 минут, периодически помешивая.", "При желании измельчите часть супа блендером, разбавьте водой до нужной густоты. Разделите на 6 порций.", "Перед едой поджарьте хлеб, положите сыр и прогрейте до размягчения. К супу подайте тост и нарезанный огурец."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
