insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m23', 'Тефтели, кускус и запечённые овощи', 'Обед', '25 мин работы · 45 мин всего', 4, false, '[25, 26]'::jsonb, '["Фарш смешайте с измельчённым луком и яйцом. Сформируйте 12 тефтелей, положите в форму с 50 мл воды.", "Кабачок и морковь нарежьте, смешайте с маслом, разложите на отдельном противне.", "Запекайте тефтели и овощи при 190 °C 25–35 минут. Моркови при необходимости дайте ещё 5–10 минут. Проверьте готовность птицы: 74 °C в центре самого толстого кусочка. Время зависит от духовки и размера порций.", "Кускус залейте кипятком в соотношении на упаковке, накройте на 5–10 минут и разрыхлите вилкой. Разделите всё на 4 порции."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
