insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m24', 'Котлеты из горбуши с картофельно-морковным пюре', 'Ужин', '25 мин работы · 45 мин всего', 4, false, '[25, 26]'::jsonb, '["С консервированной горбуши слейте жидкость. Разомните рыбу, удалите твёрдые кости; мягкие косточки можно размять. Добавьте яйца, мелко нарезанный лук и хлопья.", "Оставьте смесь на 10 минут. Сформируйте 8 котлет, положите на смазанный противень. Запекайте при 180 °C 20–25 минут до готовности яиц.", "Картофель и морковь очистите и нарежьте, варите в воде 20–25 минут до мягкости. Воду слейте, разомните с подогретым молоком.", "Разделите на 4 порции. Подайте с выбранным салатом из категории «Салаты»."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
