insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m25', 'Куриные желудочки с фасолью и булгуром', 'Обед', '25 мин работы · 100–140 мин всего', 4, false, '[27, 28]'::jsonb, '["Проверьте очищенные желудочки: удалите остатки жёлтой внутренней плёнки и лишний жир. Крупные разрежьте на 2–3 части.", "Положите в кастрюлю, залейте водой так, чтобы она покрывала желудочки на 2–3 см. Доведите до кипения, снимите пену и варите при слабом кипении под крышкой 60–90 минут, почти до мягкости. Сохраните 200–300 мл отвара.", "Лук нарежьте, морковь натрите или нарежьте тонкими брусочками. В сотейнике прогрейте их на масле 5–7 минут. Добавьте желудочки, томаты и 200 мл отвара.", "Тушите 20–30 минут до мягкости. При необходимости добавляйте отвар и увеличьте время. Желудочки должны прогреться минимум до 74 °C; готовность по мягкости проверяйте вилкой.", "Фасоль промойте, добавьте за 10 минут до конца. Булгур сварите по упаковке примерно в 560 мл воды. Разделите на 4 порции. Для быстрой готовки желудочки можно заранее отварить, быстро охладить и заморозить порциями."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
