insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m26', 'Домашний куриный бургер с запечёнными овощами', 'Ужин', '25 мин работы · 45 мин всего', 4, false, '[27, 28]'::jsonb, '["Курицу измельчите в фарш с луком, добавьте яйцо и немного соли. Сформируйте 4 плоские котлеты.", "Морковь нарежьте тонкими брусочками, кабачок — кружочками; смешайте с маслом и разложите на противне.", "Котлеты готовьте в отдельной форме при 190 °C 25–30 минут; овощи — примерно 30–40 минут. Проверьте готовность птицы: 74 °C в центре самого толстого кусочка. Время зависит от духовки и размера порций.", "Перед едой разрежьте булочку и слегка поджарьте. Добавьте йогурт, рукколу, томат и горячую котлету. Овощи подайте рядом. Для второго дня храните начинку и булочки отдельно."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
