insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m27', 'Индейка с овощами и цельнозерновыми макаронами', 'Обед', '20 мин работы · 40 мин всего', 4, false, '[29, 30]'::jsonb, '["Индейку нарежьте небольшими кубиками. Лук измельчите, морковь натрите, кабачок нарежьте.", "На масле прогрейте лук и морковь 5 минут. Добавьте индейку и готовьте ещё 5 минут.", "Добавьте кабачок, томаты и 100 мл воды. Тушите 20–25 минут до готовности индейки. Проверьте готовность птицы: 74 °C в центре самого толстого кусочка. Время зависит от духовки и размера порций.", "Макароны сварите по упаковке, смешайте с соусом. Разделите на 4 порции."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
