insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('m28', 'Чечевично-овощное рагу с яйцом', 'Ужин', '20 мин работы · 40 мин всего', 4, false, '[29, 30]'::jsonb, '["Лук и морковь нарежьте, прогрейте на масле 5 минут. Добавьте кабачок кубиками, промытую чечевицу и томаты.", "Влейте 650 мл воды. Варите 20–25 минут до мягкости чечевицы; по необходимости добавьте воду.", "Яйца сварите вкрутую 9–10 минут и охладите. Разделите рагу на 4 порции.", "К каждой порции добавьте яйцо, 50 г йогурта и 60 г хлеба. Йогурт храните отдельно от рагу."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
