insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('b1', 'Ночная овсянка с яблоком', 'Завтрак', '5 мин вечером · 2 мин утром', 2, true, '[1, 15]'::jsonb, '["В две чистые ёмкости поровну положите хлопья, йогурт и молоко. Перемешайте; чиа, если есть в составе, добавьте сейчас.", "Закройте и уберите в холодильник на ночь (не на стол).", "Утром добавьте нарезанный фрукт / размороженные ягоды, орехи или пасту из списка. Если слишком густо, добавьте немного воды."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
