insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('b5', 'Творожная запеканка с ягодами', 'Завтрак', '10 мин работы · 40 мин выпекания', 2, true, '[2]'::jsonb, '["Духовку разогрейте до 180 °C. Творог разомните с яйцом, мукой и половиной йогурта.", "Яблоко / грушу мелко нарежьте, вмешайте в массу. Ягоды можно оставить для подачи. Форму слегка смажьте указанным маслом.", "Переложите массу в небольшую форму слоем 3–4 см. Выпекайте 30–40 минут до схватывания середины.", "Разделите на две порции. Подайте с оставшимся йогуртом и ягодами, если они в составе. Для заготовки охладите и уберите в холодильник; утром разогрейте порцию."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
