insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('b8', 'Яйца с тостами и овощами', 'Завтрак', '10 мин', 2, true, '[3]'::jsonb, '["Яйца сварите вкрутую: 9–10 минут после закипания. Остудите в холодной воде и очистите.", "Хлеб поджарьте в тостере или на сухой сковороде.", "Овощи вымойте и нарежьте. Разделите всё поровну: по 2 яйца и 70 г хлеба на человека."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
