insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('b9', 'Овсянка с бананом и арахисовой пастой', 'Завтрак', '10 мин', 2, true, '[4]'::jsonb, '["Молоко смешайте со 150 мл воды, доведите до слабого кипения. Всыпьте хлопья.", "Варите на небольшом огне 5–10 минут по упаковке, помешивая.", "Разделите на две порции, добавьте банан и пасту. Йогурт подайте отдельно."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
