insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('b10', 'Яичные маффины с тостами', 'Завтрак', '10 мин работы · 25 мин выпекания', 2, true, '[5, 10, 24]'::jsonb, '["Кабачок мелко нарежьте; прогрейте на сковороде 3–4 минуты, чтобы убрать лишнюю влагу. Сыр натрите.", "Яйца взбейте с молоком, вмешайте овощи и сыр. Смажьте 4 крупные формочки маслом.", "Разлейте смесь и выпекайте при 180 °C 20–25 минут до полного схватывания.", "На человека — 2 маффина, хлеб и огурец. Если делаете сразу несколько завтраков, лишние порции быстро охладите и заморозьте; накануне переложите в холодильник."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
