insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('b11', 'Творог, груша, орехи и тосты', 'Завтрак', '5 мин', 2, true, '[6]'::jsonb, '["Грушу вымойте, нарежьте. Хлеб подсушите.", "Разделите творог на две миски, добавьте грушу и орехи, подайте с тостами. При необходимости разбавьте творог небольшим количеством воды."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
