insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('b12', 'Овсяноблин с сыром и томатом', 'Завтрак', '15 мин', 2, true, '[7]'::jsonb, '["Хлопья измельчите или используйте мелкие. Смешайте с яйцами и молоком, дайте постоять 5 минут.", "Смажьте сковороду маслом, испеките два блина на среднем огне по 2–3 минуты с каждой стороны до готовности яйца.", "На половину каждого положите сыр и томат, сложите и прогрейте минуту. Яблоко подайте отдельно."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
