insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('b13', 'Сырники с грушей', 'Завтрак', '10 мин работы · 25 мин выпекания', 2, true, '[9]'::jsonb, '["Творог разомните с яйцом и мукой. Если он влажный, сначала дайте стечь сыворотке, а не добавляйте много муки.", "Сформируйте 6 небольших сырников, выложите на слегка смазанный пергамент.", "Запекайте при 180 °C 20–25 минут, перевернув через 15 минут, до готовности.", "Разделите на две порции по 3 штуки, подайте с йогуртом и фруктом / ягодами. Для быстрого утра готовые сырники заморозьте порциями и размораживайте в холодильнике накануне."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
