insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('b16', 'Йогурт с овсянкой, бананом и орехами', 'Завтрак', '3 мин вечером · 3 мин утром', 2, true, '[11]'::jsonb, '["Вечером смешайте хлопья с йогуртом в двух ёмкостях. Если густо, добавьте по 1–2 ложки воды. Закройте и уберите в холодильник.", "Утром добавьте нарезанные фрукты и орехи."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
