insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('b18', 'Молочная гречка с творогом и яблоком', 'Завтрак', '5 мин с готовой гречкой', 2, true, '[12]'::jsonb, '["Накануне сварите 100 г сухой гречки примерно в 200 мл воды. Это дополнительная крупа к обеденному гарниру; в покупках она учтена.", "Утром добавьте молоко, прогрейте до горячего состояния и разделите на две порции.", "Творог и нарезанное яблоко подайте отдельно; корица по желанию."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
