insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('b19', 'Тосты с хумусом, яйцами и овощами', 'Завтрак', '10 мин', 2, true, '[13, 20]'::jsonb, '["Яйца сварите вкрутую 9–10 минут, остудите и очистите. Можно сделать накануне.", "Хлеб подсушите, намажьте хумусом.", "Подайте каждому по 2 яйца, половину тостов и овощей. Для точного списка покупок выбран хумус, а не альтернативный авокадо."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
