insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('b20', 'Ролл с омлетом и сыром', 'Завтрак', '10 мин', 2, true, '[16]'::jsonb, '["Яйца смешайте с молоком, вылейте на смазанную сковороду. Готовьте под крышкой 5–7 минут до схватывания.", "Лаваш разделите на две порции. Выложите омлет, сыр и нарезанные овощи.", "Сверните роллы, прогрейте на сухой сковороде по минуте с каждой стороны."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
