insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('b21', 'Пшённая каша с тыквой и творогом', 'Завтрак', '5 мин утром при заготовке', 2, true, '[18]'::jsonb, '["Пшено промойте несколько раз и обдайте кипятком. Тыкву мелко нарежьте.", "Добавьте к пшену и тыкве молоко и 200 мл воды; варите на слабом огне 20–25 минут, помешивая. При необходимости долейте воду.", "Разделите на две порции. Подайте с указанным творогом или йогуртом, грушей и орехами. Можно сразу сварить основу на дни 18–19: суммируйте пшено, тыкву и молоко двух рецептов, затем разделите на 4 порции."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
