insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('b23', 'Овсяноблин с творогом и ягодами', 'Завтрак', '15 мин', 2, true, '[21]'::jsonb, '["Смешайте хлопья, яйца и молоко, оставьте на 5 минут.", "На смазанной сковороде испеките два блина по 2–3 минуты с каждой стороны до готовности яйца.", "Творог разомните, распределите по блинам, добавьте ягоды и сложите пополам."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
