insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('b24', 'Овсянка с яблоком и творогом', 'Завтрак', '10 мин', 2, true, '[27]'::jsonb, '["Доведите молоко со 150 мл воды до слабого кипения, добавьте хлопья. Варите 5–10 минут по упаковке.", "Яблоко нарежьте и добавьте в конце или подайте свежим.", "Разделите кашу на две порции, творог подайте рядом."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
