insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('b25', 'Омлет с горошком и сыром', 'Завтрак', '10 мин', 2, true, '[28]'::jsonb, '["Горошек прогрейте на смазанной сковороде с 2 ложками воды 3–4 минуты.", "Яйца взбейте с молоком, залейте горошек, посыпьте сыром.", "Накройте и готовьте на слабом огне 5–7 минут до схватывания середины. Разделите пополам, подайте с тостами."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
