insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('s1', 'Капустный салат с укропом, зелёным луком и сметаной', 'Салат', '5–10 мин с готовыми заготовками', 2, true, '[22, 23, 24]'::jsonb, '["Капусту тонко нашинкуйте и слегка помните руками. Морковь натрите; зелень вымойте и обсушите.", "Нарежьте укроп и зелёный лук, соедините с овощами. Сметану перемешайте с 1–2 ч. л. воды, если она густая.", "Непосредственно перед едой заправьте салат, попробуйте и при необходимости слегка посолите. Разделите на две порции.", "Капусту и морковь можно подготовить на 2–3 дня и хранить в закрытых контейнерах в холодильнике. Зелень и сметану добавляйте только к сегодняшним порциям."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
