insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('s2', 'Руккола с томатами, огурцом и лимонной заправкой', 'Салат', '5–10 мин с готовыми заготовками', 2, true, '[4, 5, 27, 28]'::jsonb, '["Рукколу переберите, вымойте и хорошо обсушите. Томаты нарежьте дольками, огурец — полукружьями.", "Смешайте масло с 1–2 ч. л. лимонного сока из указанного лимона. Остальной лимон сохраните для другой подачи.", "Соедините овощи с рукколой, полейте заправкой перед едой и осторожно перемешайте. Подайте на двоих."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
