insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('s3', 'Шпинат с огурцом, яйцом и йогуртовой заправкой', 'Салат', '5–10 мин с готовыми заготовками', 2, true, '[6, 7]'::jsonb, '["Яйцо сварите вкрутую 9–10 минут, охладите и очистите. Для двух дней можно сразу сварить 2 яйца.", "Шпинат и зелень вымойте, обсушите. Огурец нарежьте полукружьями, яйцо — небольшими кусочками.", "Йогурт смешайте с мелко нарезанным укропом и зелёным луком. Добавьте к шпинату, огурцу и яйцу непосредственно перед едой.", "Осторожно перемешайте и разделите на две порции. Не храните заправленный шпинат на следующий день."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
