insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('s4', 'Свёкла со шпинатом, орехами и йогуртом', 'Салат', '5–10 мин с готовыми заготовками', 2, true, '[18, 19]'::jsonb, '["Свёклу отварите до мягкости или запеките в закрытой форме при 200 °C 50–70 минут. Можно использовать готовую варёную свёклу. Полностью охладите.", "Нарежьте свёклу небольшими кубиками. Шпинат и укроп вымойте и обсушите, орехи порубите.", "Выложите шпинат на две тарелки, сверху добавьте свёклу. Йогурт смешайте с укропом, распределите по салату и посыпьте орехами.", "Свёклу можно сварить на 2–3 дня. Шпинат, йогурт и орехи добавляйте перед подачей."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
