insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('s5', 'Морковь и яблоко с рукколой и йогуртом', 'Салат', '5–10 мин с готовыми заготовками', 2, true, '[]'::jsonb, '["Морковь натрите крупно, яблоко нарежьте тонкой соломкой. Сбрызните яблоко 1 ч. л. лимонного сока.", "Рукколу вымойте и обсушите. Соедините с морковью и яблоком.", "Добавьте йогурт, аккуратно перемешайте и подайте на двоих. Яблоко режьте перед едой, чтобы оно не темнело."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
