insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('s6', 'Томаты и огурцы с зелёным луком и сметаной', 'Салат', '5–10 мин с готовыми заготовками', 2, true, '[13, 14]'::jsonb, '["Овощи и зелень вымойте. Томаты нарежьте дольками, огурцы — полукружьями; зелень обсушите и мелко нарежьте.", "Соедините в миске, добавьте сметану и небольшое количество соли по вкусу.", "Перемешайте непосредственно перед едой. Разделите на две порции; заранее заправлять не нужно — овощи дадут сок."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
