insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('s7', 'Свёкла с яблоком, зелёным луком и сметаной', 'Салат', '5–10 мин с готовыми заготовками', 2, true, '[15, 16, 17]'::jsonb, '["Свёклу заранее сварите до мягкости, охладите и натрите крупно. Можно подготовить сразу на 3 дня.", "Перед подачей натрите яблоко. Зелёный лук и укроп вымойте, обсушите и измельчите.", "Смешайте свёклу, яблоко и зелень со сметаной. Разделите на две порции. Сладости яблока и свёклы достаточно, сахар не нужен."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
