insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('s8', 'Редис и огурец с укропом и сметаной', 'Салат', '5–10 мин с готовыми заготовками', 2, true, '[]'::jsonb, '["Редис и огурец вымойте, срежьте кончики. Нарежьте тонкими кружочками или полукружьями.", "Укроп и зелёный лук вымойте, обсушите и мелко нарежьте.", "Соедините овощи и зелень, добавьте сметану и слегка посолите по вкусу. Перемешайте перед едой и разделите на две порции."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
