insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('s9', 'Шпинат с огурцом, горошком и йогуртом', 'Салат', '5–10 мин с готовыми заготовками', 2, true, '[]'::jsonb, '["Замороженный горошек отварите по инструкции на упаковке, обычно 3–5 минут, откиньте на сито и охладите. Можно приготовить сразу на два дня.", "Шпинат, огурец и зелень вымойте. Зелень обсушите, огурец нарежьте полукружьями.", "Йогурт смешайте с измельчёнными укропом и зелёным луком. Соедините всё перед едой, разделите на две порции."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
