insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('s10', 'Руккола с грушей, сыром и орехами', 'Салат', '5–10 мин с готовыми заготовками', 2, true, '[29, 30]'::jsonb, '["Рукколу вымойте и обсушите. Грушу нарежьте тонкими дольками, твёрдый сыр — тонкими полосками. Орехи порубите.", "Йогурт смешайте с 1 ч. л. лимонного сока; если нужно, добавьте ложку воды для более жидкой заправки.", "Выложите рукколу, грушу и сыр на две тарелки. Полейте заправкой и посыпьте орехами перед подачей."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
