insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('s11', 'Капуста с морковью и растительным маслом', 'Салат', '5–10 мин с готовыми заготовками', 2, true, '[1, 2, 3]'::jsonb, '["Капусту тонко нашинкуйте. Морковь очистите и натрите крупно.", "Слегка помните капусту руками, соедините с морковью. Добавьте масло и небольшое количество соли по вкусу.", "Разделите на две порции. Овощи можно нашинковать на 2–3 дня, хранить в холодильнике и заправлять порционно перед едой."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
