insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('s12', 'Простой свекольный салат', 'Салат', '5–10 мин с готовыми заготовками', 2, true, '[8, 9, 10]'::jsonb, '["Свёклу заранее отварите до мягкости или запеките в закрытой форме при 200 °C 50–70 минут. Можно взять готовую варёную свёклу.", "Охладите, очистите и натрите крупно или нарежьте небольшими кубиками.", "Заправьте маслом, при необходимости слегка посолите. Разделите на две порции. Свёклу удобно сварить сразу на 2–3 дня."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
