insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('s13', 'Морковно-яблочный салат с лимоном', 'Салат', '5–10 мин с готовыми заготовками', 2, true, '[11, 12]'::jsonb, '["Морковь вымойте, очистите и натрите. Яблоко вымойте, удалите сердцевину и натрите или нарежьте соломкой.", "Добавьте примерно 1 ч. л. лимонного сока из указанного лимона и растительное масло, перемешайте.", "Разделите на две порции. Морковь можно подготовить заранее, яблоко добавляйте перед едой."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
