insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('s14', 'Огурцы с укропом', 'Салат', '5–10 мин с готовыми заготовками', 2, true, '[25, 26]'::jsonb, '["Огурцы и укроп вымойте, укроп хорошо обсушите.", "Огурцы нарежьте полукружьями, укроп мелко порубите.", "Добавьте масло, перемешайте, при необходимости слегка посолите. Подайте сразу на двоих."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
