insert into public.recipes (id, title, meal, mins, servings, per_occurrence, days, steps, tip, description, is_custom) values ('s15', 'Помидоры и огурцы с растительным маслом', 'Салат', '5–10 мин с готовыми заготовками', 2, true, '[20, 21]'::jsonb, '["Овощи вымойте, помидоры нарежьте дольками, огурцы — полукружьями.", "Соедините в миске, добавьте масло и немного соли по вкусу.", "Аккуратно перемешайте и разделите на две порции. Собирайте перед едой, чтобы овощи не дали слишком много сока."]'::jsonb, '', '', false) on conflict (id) do update set title=excluded.title, meal=excluded.meal, mins=excluded.mins, servings=excluded.servings, per_occurrence=excluded.per_occurrence, days=excluded.days, steps=excluded.steps, tip=excluded.tip, is_custom=excluded.is_custom;
